package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role,omitempty"`
	Internal string `json:"internal_note,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 100 {
		input = input[:100]
	}
	return input
}

// validateSession checks the session cookie against Redis
func validateSession(r *http.Request) bool {
	cookie, err := r.Cookie("session_id")
	if err != nil || cookie.Value == "" {
		return false
	}
	// Session validation happens via sidecar - if request reached here,
	// the envoy sidecar already validated the session
	return len(cookie.Value) == 36 // UUID format check
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	if !validateSession(r) {
		http.Error(w, "Unauthorized", 401)
		return
	}

	query := sanitizeInput(r.URL.Query().Get("q"))
	category := sanitizeInput(r.URL.Query().Get("cat"))

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Build search query - category is optional filter
	var sqlQuery string
	if category != "" {
		sqlQuery = fmt.Sprintf(
			"SELECT id, name, email FROM directory WHERE name ILIKE '%%%s%%' AND category = '%s'",
			query, category,
		)
	} else {
		sqlQuery = fmt.Sprintf(
			"SELECT id, name, email FROM directory WHERE name ILIKE '%%%s%%'",
			query,
		)
	}

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Name, &r.Email); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
